SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
GO

CREATE SCHEMA core; GO
CREATE SCHEMA acc; GO
CREATE SCHEMA ap; GO
CREATE SCHEMA ar; GO
CREATE SCHEMA imp; GO
CREATE SCHEMA inv; GO
CREATE SCHEMA trs; GO
CREATE SCHEMA tax; GO
CREATE SCHEMA pay; GO
CREATE SCHEMA fpna; GO
CREATE SCHEMA ai; GO
CREATE SCHEMA ctrl; GO
CREATE SCHEMA audit; GO
CREATE SCHEMA integration; GO

CREATE TABLE core.Company(
 CompanyId BIGINT IDENTITY CONSTRAINT PK_Company PRIMARY KEY, CompanyCode VARCHAR(20) NOT NULL,
 CompanyNameAr NVARCHAR(200) NOT NULL, CompanyNameEn NVARCHAR(200) NULL, BaseCurrency CHAR(3) NOT NULL,
 TaxRegistrationNo VARCHAR(50) NULL, IsActive BIT NOT NULL CONSTRAINT DF_Company_Active DEFAULT(1),
 CreatedAt DATETIME2(3) NOT NULL CONSTRAINT DF_Company_Created DEFAULT SYSUTCDATETIME(),
 CONSTRAINT UQ_Company_Code UNIQUE(CompanyCode));
CREATE TABLE core.Branch(BranchId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,BranchCode VARCHAR(20) NOT NULL,BranchName NVARCHAR(200) NOT NULL,IsActive BIT NOT NULL DEFAULT(1),CONSTRAINT FK_Branch_Company FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),CONSTRAINT UQ_Branch UNIQUE(CompanyId,BranchCode));
CREATE TABLE core.FiscalYear(FiscalYearId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,YearCode VARCHAR(20) NOT NULL,StartDate DATE NOT NULL,EndDate DATE NOT NULL,IsClosed BIT NOT NULL DEFAULT(0),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),CHECK(StartDate<=EndDate),UNIQUE(CompanyId,YearCode));
CREATE TABLE core.FiscalPeriod(FiscalPeriodId BIGINT IDENTITY PRIMARY KEY,FiscalYearId BIGINT NOT NULL,PeriodNo SMALLINT NOT NULL,PeriodName NVARCHAR(50),StartDate DATE NOT NULL,EndDate DATE NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('OPEN'),FOREIGN KEY(FiscalYearId) REFERENCES core.FiscalYear(FiscalYearId),CHECK(StartDate<=EndDate),CHECK(Status IN('OPEN','SOFT_CLOSED','CLOSED')),UNIQUE(FiscalYearId,PeriodNo));
CREATE TABLE core.Currency(CurrencyCode CHAR(3) PRIMARY KEY,CurrencyName NVARCHAR(100) NOT NULL,DecimalPlaces TINYINT NOT NULL DEFAULT(2),IsActive BIT NOT NULL DEFAULT(1));
CREATE TABLE core.ExchangeRate(ExchangeRateId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,RateDate DATE NOT NULL,FromCurrency CHAR(3) NOT NULL,ToCurrency CHAR(3) NOT NULL,RateType VARCHAR(20) NOT NULL DEFAULT('SPOT'),Rate DECIMAL(28,12) NOT NULL,FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(FromCurrency) REFERENCES core.Currency(CurrencyCode),FOREIGN KEY(ToCurrency) REFERENCES core.Currency(CurrencyCode),CHECK(Rate>0),UNIQUE(CompanyId,RateDate,FromCurrency,ToCurrency,RateType));
CREATE TABLE core.Department(DepartmentId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,DepartmentCode VARCHAR(30) NOT NULL,DepartmentName NVARCHAR(200) NOT NULL,IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),UNIQUE(CompanyId,DepartmentCode));
CREATE TABLE core.CostCenter(CostCenterId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,CostCenterCode VARCHAR(30) NOT NULL,CostCenterName NVARCHAR(200) NOT NULL,IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),UNIQUE(CompanyId,CostCenterCode));
CREATE TABLE core.Dimension(DimensionId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,DimensionType VARCHAR(40) NOT NULL,DimensionCode VARCHAR(50) NOT NULL,DimensionName NVARCHAR(200) NOT NULL,IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),UNIQUE(CompanyId,DimensionType,DimensionCode));
CREATE TABLE core.AppUser(UserId BIGINT IDENTITY PRIMARY KEY,ExternalObjectId VARCHAR(100) NULL,UserName NVARCHAR(200) NOT NULL,Email NVARCHAR(320) NULL,IsActive BIT NOT NULL DEFAULT(1),UNIQUE(ExternalObjectId));
CREATE TABLE core.AppRole(RoleId BIGINT IDENTITY PRIMARY KEY,RoleCode VARCHAR(50) NOT NULL UNIQUE,RoleName NVARCHAR(150) NOT NULL,IsActive BIT NOT NULL DEFAULT(1));
CREATE TABLE core.UserRole(UserId BIGINT NOT NULL,RoleId BIGINT NOT NULL,CompanyId BIGINT NOT NULL,ValidFrom DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),ValidTo DATETIME2(3) NULL,PRIMARY KEY(UserId,RoleId,CompanyId),FOREIGN KEY(UserId) REFERENCES core.AppUser(UserId),FOREIGN KEY(RoleId) REFERENCES core.AppRole(RoleId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId));
CREATE TABLE core.BusinessTransaction(TransactionId BIGINT IDENTITY PRIMARY KEY,TransactionNumber VARCHAR(50) NOT NULL UNIQUE,CompanyId BIGINT NOT NULL,TransactionType VARCHAR(40) NOT NULL,SourceSystem VARCHAR(50) NULL,SourceReference VARCHAR(100) NULL,Status VARCHAR(30) NOT NULL DEFAULT('DRAFT'),CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CompletedAt DATETIME2(3) NULL,FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId));

CREATE TABLE acc.Account(AccountId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,AccountCode VARCHAR(50) NOT NULL,AccountNameAr NVARCHAR(250) NOT NULL,AccountNameEn NVARCHAR(250),ParentAccountId BIGINT NULL,AccountType VARCHAR(30) NOT NULL,NormalBalance CHAR(1) NOT NULL,AllowPosting BIT NOT NULL DEFAULT(1),RequiresCostCenter BIT NOT NULL DEFAULT(0),IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(ParentAccountId) REFERENCES acc.Account(AccountId),CHECK(NormalBalance IN('D','C')),UNIQUE(CompanyId,AccountCode));
CREATE TABLE acc.JournalHeader(JournalId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,CompanyId BIGINT NOT NULL,JournalNumber VARCHAR(50) NOT NULL,JournalType VARCHAR(30) NOT NULL,SourceModule VARCHAR(30) NOT NULL,DocumentNumber VARCHAR(100) NULL,DocumentDate DATE NULL,PostingDate DATE NOT NULL,CurrencyCode CHAR(3) NOT NULL,ExchangeRate DECIMAL(28,12) NOT NULL DEFAULT(1),Status VARCHAR(25) NOT NULL DEFAULT('DRAFT'),Description NVARCHAR(500),PreparedBy BIGINT NULL,ApprovedBy BIGINT NULL,PostedAt DATETIME2(3) NULL,CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),FOREIGN KEY(PreparedBy) REFERENCES core.AppUser(UserId),FOREIGN KEY(ApprovedBy) REFERENCES core.AppUser(UserId),CHECK(ExchangeRate>0),CHECK(Status IN('DRAFT','PENDING_APPROVAL','APPROVED','POSTED','REJECTED','REVERSED')),UNIQUE(CompanyId,JournalNumber));
CREATE TABLE acc.JournalLine(JournalLineId BIGINT IDENTITY PRIMARY KEY,JournalId BIGINT NOT NULL,LineNo INT NOT NULL,AccountId BIGINT NOT NULL,Debit DECIMAL(28,6) NOT NULL DEFAULT(0),Credit DECIMAL(28,6) NOT NULL DEFAULT(0),TransactionAmount DECIMAL(28,6) NULL,CostCenterId BIGINT NULL,DepartmentId BIGINT NULL,DimensionId BIGINT NULL,Reference VARCHAR(100) NULL,Description NVARCHAR(500) NULL,FOREIGN KEY(JournalId) REFERENCES acc.JournalHeader(JournalId),FOREIGN KEY(AccountId) REFERENCES acc.Account(AccountId),FOREIGN KEY(CostCenterId) REFERENCES core.CostCenter(CostCenterId),FOREIGN KEY(DepartmentId) REFERENCES core.Department(DepartmentId),FOREIGN KEY(DimensionId) REFERENCES core.Dimension(DimensionId),CHECK(Debit>=0 AND Credit>=0),CHECK((Debit>0 AND Credit=0) OR (Credit>0 AND Debit=0)),UNIQUE(JournalId,LineNo));

CREATE TABLE ap.Vendor(VendorId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,VendorCode VARCHAR(40) NOT NULL,VendorName NVARCHAR(250) NOT NULL,TaxRegistrationNo VARCHAR(50),DefaultCurrency CHAR(3) NULL,PaymentTermsDays INT NOT NULL DEFAULT(0),IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(DefaultCurrency) REFERENCES core.Currency(CurrencyCode),CHECK(PaymentTermsDays>=0),UNIQUE(CompanyId,VendorCode));
CREATE TABLE ap.PurchaseOrder(PurchaseOrderId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,CompanyId BIGINT NOT NULL,VendorId BIGINT NOT NULL,PONumber VARCHAR(50) NOT NULL,PODate DATE NOT NULL,CurrencyCode CHAR(3) NOT NULL,ExchangeRate DECIMAL(28,12) NOT NULL DEFAULT(1),Status VARCHAR(25) NOT NULL DEFAULT('OPEN'),TotalAmount DECIMAL(28,6) NOT NULL DEFAULT(0),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(VendorId) REFERENCES ap.Vendor(VendorId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),CHECK(TotalAmount>=0),UNIQUE(CompanyId,PONumber));
CREATE TABLE ap.PurchaseOrderLine(POLineId BIGINT IDENTITY PRIMARY KEY,PurchaseOrderId BIGINT NOT NULL,LineNo INT NOT NULL,ItemId BIGINT NULL,Description NVARCHAR(500),Quantity DECIMAL(28,6) NOT NULL,UnitPrice DECIMAL(28,6) NOT NULL,TaxCode VARCHAR(30) NULL,FOREIGN KEY(PurchaseOrderId) REFERENCES ap.PurchaseOrder(PurchaseOrderId),CHECK(Quantity>0 AND UnitPrice>=0),UNIQUE(PurchaseOrderId,LineNo));
CREATE TABLE ap.GoodsReceipt(GoodsReceiptId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,CompanyId BIGINT NOT NULL,PurchaseOrderId BIGINT NOT NULL,GRNumber VARCHAR(50) NOT NULL,ReceiptDate DATE NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('RECEIVED'),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(PurchaseOrderId) REFERENCES ap.PurchaseOrder(PurchaseOrderId),UNIQUE(CompanyId,GRNumber));
CREATE TABLE ap.GoodsReceiptLine(GRLineId BIGINT IDENTITY PRIMARY KEY,GoodsReceiptId BIGINT NOT NULL,POLineId BIGINT NOT NULL,LineNo INT NOT NULL,QuantityReceived DECIMAL(28,6) NOT NULL,FOREIGN KEY(GoodsReceiptId) REFERENCES ap.GoodsReceipt(GoodsReceiptId),FOREIGN KEY(POLineId) REFERENCES ap.PurchaseOrderLine(POLineId),CHECK(QuantityReceived>0),UNIQUE(GoodsReceiptId,LineNo));
CREATE TABLE ap.SupplierInvoice(InvoiceId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,CompanyId BIGINT NOT NULL,VendorId BIGINT NOT NULL,PurchaseOrderId BIGINT NULL,InvoiceNumber VARCHAR(100) NOT NULL,InvoiceDate DATE NOT NULL,ReceivedDate DATE NULL,DueDate DATE NULL,CurrencyCode CHAR(3) NOT NULL,ExchangeRate DECIMAL(28,12) NOT NULL DEFAULT(1),GrossAmount DECIMAL(28,6) NOT NULL,DiscountAmount DECIMAL(28,6) NOT NULL DEFAULT(0),TaxAmount DECIMAL(28,6) NOT NULL DEFAULT(0),WithholdingAmount DECIMAL(28,6) NOT NULL DEFAULT(0),NetAmount DECIMAL(28,6) NOT NULL,MatchingStatus VARCHAR(25) NOT NULL DEFAULT('UNMATCHED'),ApprovalStatus VARCHAR(25) NOT NULL DEFAULT('PENDING'),PostingStatus VARCHAR(25) NOT NULL DEFAULT('UNPOSTED'),ExternalDocumentId VARCHAR(100) NULL,D365Reference VARCHAR(100) NULL,CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(VendorId) REFERENCES ap.Vendor(VendorId),FOREIGN KEY(PurchaseOrderId) REFERENCES ap.PurchaseOrder(PurchaseOrderId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),CHECK(GrossAmount>=0 AND DiscountAmount>=0 AND TaxAmount>=0 AND WithholdingAmount>=0 AND NetAmount>=0),UNIQUE(CompanyId,VendorId,InvoiceNumber));
CREATE TABLE ap.SupplierInvoiceLine(InvoiceLineId BIGINT IDENTITY PRIMARY KEY,InvoiceId BIGINT NOT NULL,LineNo INT NOT NULL,POLineId BIGINT NULL,Description NVARCHAR(500),Quantity DECIMAL(28,6) NOT NULL DEFAULT(1),UnitPrice DECIMAL(28,6) NOT NULL DEFAULT(0),TaxAmount DECIMAL(28,6) NOT NULL DEFAULT(0),LineAmount DECIMAL(28,6) NOT NULL,FOREIGN KEY(InvoiceId) REFERENCES ap.SupplierInvoice(InvoiceId),FOREIGN KEY(POLineId) REFERENCES ap.PurchaseOrderLine(POLineId),CHECK(Quantity>0 AND UnitPrice>=0 AND TaxAmount>=0 AND LineAmount>=0),UNIQUE(InvoiceId,LineNo));
CREATE TABLE ap.InvoiceMatch(InvoiceMatchId BIGINT IDENTITY PRIMARY KEY,InvoiceId BIGINT NOT NULL,InvoiceLineId BIGINT NULL,POLineId BIGINT NULL,GRLineId BIGINT NULL,MatchType VARCHAR(25) NOT NULL,QtyVariance DECIMAL(28,6) NULL,PriceVariance DECIMAL(28,6) NULL,Result VARCHAR(20) NOT NULL,MatchedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),FOREIGN KEY(InvoiceId) REFERENCES ap.SupplierInvoice(InvoiceId),FOREIGN KEY(InvoiceLineId) REFERENCES ap.SupplierInvoiceLine(InvoiceLineId),FOREIGN KEY(POLineId) REFERENCES ap.PurchaseOrderLine(POLineId),FOREIGN KEY(GRLineId) REFERENCES ap.GoodsReceiptLine(GRLineId),CHECK(Result IN('PASS','WARNING','FAIL','BLOCK')));
CREATE TABLE ap.PaymentSchedule(PaymentScheduleId BIGINT IDENTITY PRIMARY KEY,InvoiceId BIGINT NOT NULL,DueDate DATE NOT NULL,Amount DECIMAL(28,6) NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('OPEN'),FOREIGN KEY(InvoiceId) REFERENCES ap.SupplierInvoice(InvoiceId),CHECK(Amount>0));

CREATE TABLE ar.Customer(CustomerId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,CustomerCode VARCHAR(40) NOT NULL,CustomerName NVARCHAR(250) NOT NULL,TaxRegistrationNo VARCHAR(50),DefaultCurrency CHAR(3) NULL,PaymentTermsDays INT NOT NULL DEFAULT(0),IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(DefaultCurrency) REFERENCES core.Currency(CurrencyCode),CHECK(PaymentTermsDays>=0),UNIQUE(CompanyId,CustomerCode));
CREATE TABLE ar.CustomerCreditProfile(CustomerCreditProfileId BIGINT IDENTITY PRIMARY KEY,CustomerId BIGINT NOT NULL,CreditLimit DECIMAL(28,6) NOT NULL DEFAULT(0),RiskRating VARCHAR(20) NULL,ValidFrom DATE NOT NULL,ValidTo DATE NULL,FOREIGN KEY(CustomerId) REFERENCES ar.Customer(CustomerId),CHECK(CreditLimit>=0));
CREATE TABLE ar.SalesInvoice(SalesInvoiceId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,CompanyId BIGINT NOT NULL,CustomerId BIGINT NOT NULL,InvoiceNumber VARCHAR(100) NOT NULL,InvoiceDate DATE NOT NULL,DueDate DATE NULL,CurrencyCode CHAR(3) NOT NULL,ExchangeRate DECIMAL(28,12) NOT NULL DEFAULT(1),GrossAmount DECIMAL(28,6) NOT NULL,TaxAmount DECIMAL(28,6) NOT NULL DEFAULT(0),NetAmount DECIMAL(28,6) NOT NULL,Status VARCHAR(25) NOT NULL DEFAULT('OPEN'),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(CustomerId) REFERENCES ar.Customer(CustomerId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),UNIQUE(CompanyId,InvoiceNumber));
CREATE TABLE ar.SalesInvoiceLine(SalesInvoiceLineId BIGINT IDENTITY PRIMARY KEY,SalesInvoiceId BIGINT NOT NULL,LineNo INT NOT NULL,ItemId BIGINT NULL,Description NVARCHAR(500),Quantity DECIMAL(28,6) NOT NULL,UnitPrice DECIMAL(28,6) NOT NULL,TaxAmount DECIMAL(28,6) NOT NULL DEFAULT(0),LineAmount DECIMAL(28,6) NOT NULL,FOREIGN KEY(SalesInvoiceId) REFERENCES ar.SalesInvoice(SalesInvoiceId),CHECK(Quantity>0 AND UnitPrice>=0),UNIQUE(SalesInvoiceId,LineNo));
CREATE TABLE ar.Receipt(ReceiptId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,CompanyId BIGINT NOT NULL,CustomerId BIGINT NOT NULL,ReceiptNumber VARCHAR(50) NOT NULL,ReceiptDate DATE NOT NULL,CurrencyCode CHAR(3) NOT NULL,Amount DECIMAL(28,6) NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('RECEIVED'),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(CustomerId) REFERENCES ar.Customer(CustomerId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),CHECK(Amount>0),UNIQUE(CompanyId,ReceiptNumber));
CREATE TABLE ar.ReceiptAllocation(ReceiptAllocationId BIGINT IDENTITY PRIMARY KEY,ReceiptId BIGINT NOT NULL,SalesInvoiceId BIGINT NOT NULL,AllocatedAmount DECIMAL(28,6) NOT NULL,FOREIGN KEY(ReceiptId) REFERENCES ar.Receipt(ReceiptId),FOREIGN KEY(SalesInvoiceId) REFERENCES ar.SalesInvoice(SalesInvoiceId),CHECK(AllocatedAmount>0),UNIQUE(ReceiptId,SalesInvoiceId));
CREATE TABLE ar.AgingSnapshot(AgingSnapshotId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,CustomerId BIGINT NOT NULL,SnapshotDate DATE NOT NULL,CurrentAmount DECIMAL(28,6) NOT NULL DEFAULT(0),Days1To30 DECIMAL(28,6) NOT NULL DEFAULT(0),Days31To60 DECIMAL(28,6) NOT NULL DEFAULT(0),Days61To90 DECIMAL(28,6) NOT NULL DEFAULT(0),Days90Plus DECIMAL(28,6) NOT NULL DEFAULT(0),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(CustomerId) REFERENCES ar.Customer(CustomerId),UNIQUE(CompanyId,CustomerId,SnapshotDate));
CREATE TABLE ar.CollectionAction(CollectionActionId BIGINT IDENTITY PRIMARY KEY,CustomerId BIGINT NOT NULL,SalesInvoiceId BIGINT NULL,ActionDate DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),ActionType VARCHAR(30) NOT NULL,Notes NVARCHAR(1000),OwnerUserId BIGINT NULL,FOREIGN KEY(CustomerId) REFERENCES ar.Customer(CustomerId),FOREIGN KEY(SalesInvoiceId) REFERENCES ar.SalesInvoice(SalesInvoiceId),FOREIGN KEY(OwnerUserId) REFERENCES core.AppUser(UserId));

CREATE TABLE inv.Item(ItemId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,ItemCode VARCHAR(50) NOT NULL,ItemName NVARCHAR(250) NOT NULL,ItemGroupCode VARCHAR(40) NULL,BaseUOM VARCHAR(20) NOT NULL,Weight DECIMAL(28,6) NULL,Volume DECIMAL(28,6) NULL,IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),UNIQUE(CompanyId,ItemCode));
ALTER TABLE ap.PurchaseOrderLine ADD CONSTRAINT FK_POLine_Item FOREIGN KEY(ItemId) REFERENCES inv.Item(ItemId);
ALTER TABLE ar.SalesInvoiceLine ADD CONSTRAINT FK_SalesLine_Item FOREIGN KEY(ItemId) REFERENCES inv.Item(ItemId);
CREATE TABLE inv.Warehouse(WarehouseId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,WarehouseCode VARCHAR(30) NOT NULL,WarehouseName NVARCHAR(200) NOT NULL,IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),UNIQUE(CompanyId,WarehouseCode));
CREATE TABLE inv.InventoryTransaction(InventoryTransactionId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,CompanyId BIGINT NOT NULL,ItemId BIGINT NOT NULL,WarehouseId BIGINT NOT NULL,TransactionDate DATETIME2(3) NOT NULL,TransactionType VARCHAR(30) NOT NULL,Quantity DECIMAL(28,6) NOT NULL,UnitCost DECIMAL(28,6) NULL,TotalCost DECIMAL(28,6) NULL,Reference VARCHAR(100) NULL,FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(ItemId) REFERENCES inv.Item(ItemId),FOREIGN KEY(WarehouseId) REFERENCES inv.Warehouse(WarehouseId),CHECK(Quantity<>0));
CREATE TABLE inv.InventoryBalance(InventoryBalanceId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,ItemId BIGINT NOT NULL,WarehouseId BIGINT NOT NULL,AsOfDate DATE NOT NULL,QuantityOnHand DECIMAL(28,6) NOT NULL,InventoryValue DECIMAL(28,6) NOT NULL,FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(ItemId) REFERENCES inv.Item(ItemId),FOREIGN KEY(WarehouseId) REFERENCES inv.Warehouse(WarehouseId),UNIQUE(CompanyId,ItemId,WarehouseId,AsOfDate));
CREATE TABLE inv.InventoryCostLayer(CostLayerId BIGINT IDENTITY PRIMARY KEY,ItemId BIGINT NOT NULL,WarehouseId BIGINT NOT NULL,SourceTransactionId BIGINT NULL,LayerDate DATE NOT NULL,QuantityOriginal DECIMAL(28,6) NOT NULL,QuantityRemaining DECIMAL(28,6) NOT NULL,UnitCost DECIMAL(28,6) NOT NULL,FOREIGN KEY(ItemId) REFERENCES inv.Item(ItemId),FOREIGN KEY(WarehouseId) REFERENCES inv.Warehouse(WarehouseId),FOREIGN KEY(SourceTransactionId) REFERENCES inv.InventoryTransaction(InventoryTransactionId));
CREATE TABLE inv.InventoryValuation(InventoryValuationId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,ItemId BIGINT NOT NULL,WarehouseId BIGINT NOT NULL,ValuationDate DATE NOT NULL,Method VARCHAR(20) NOT NULL,Quantity DECIMAL(28,6) NOT NULL,UnitCost DECIMAL(28,6) NOT NULL,TotalValue DECIMAL(28,6) NOT NULL,FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(ItemId) REFERENCES inv.Item(ItemId),FOREIGN KEY(WarehouseId) REFERENCES inv.Warehouse(WarehouseId));

CREATE TABLE imp.ImportCase(ImportCaseId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NOT NULL,CompanyId BIGINT NOT NULL,PurchaseOrderId BIGINT NULL,VendorId BIGINT NOT NULL,ImportNumber VARCHAR(50) NOT NULL,Status VARCHAR(25) NOT NULL DEFAULT('OPEN'),OpenedDate DATE NOT NULL,ClosedDate DATE NULL,FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(PurchaseOrderId) REFERENCES ap.PurchaseOrder(PurchaseOrderId),FOREIGN KEY(VendorId) REFERENCES ap.Vendor(VendorId),UNIQUE(CompanyId,ImportNumber));
CREATE TABLE imp.LetterOfCredit(LCId BIGINT IDENTITY PRIMARY KEY,ImportCaseId BIGINT NOT NULL,LCNumber VARCHAR(100) NOT NULL,IssuingBank NVARCHAR(200) NULL,IssueDate DATE NULL,ExpiryDate DATE NULL,CurrencyCode CHAR(3) NOT NULL,Amount DECIMAL(28,6) NOT NULL,Status VARCHAR(25) NOT NULL DEFAULT('OPEN'),FOREIGN KEY(ImportCaseId) REFERENCES imp.ImportCase(ImportCaseId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),CHECK(Amount>=0),UNIQUE(LCNumber));
CREATE TABLE imp.Shipment(ShipmentId BIGINT IDENTITY PRIMARY KEY,ImportCaseId BIGINT NOT NULL,ShipmentNumber VARCHAR(100) NOT NULL,ShipmentDate DATE NULL,ExpectedArrivalDate DATE NULL,ActualArrivalDate DATE NULL,BLNumber VARCHAR(100) NULL,Status VARCHAR(25) NOT NULL DEFAULT('PLANNED'),FOREIGN KEY(ImportCaseId) REFERENCES imp.ImportCase(ImportCaseId),UNIQUE(ImportCaseId,ShipmentNumber));
CREATE TABLE imp.ShipmentItem(ShipmentItemId BIGINT IDENTITY PRIMARY KEY,ShipmentId BIGINT NOT NULL,ItemId BIGINT NOT NULL,POLineId BIGINT NULL,Quantity DECIMAL(28,6) NOT NULL,Weight DECIMAL(28,6) NULL,Volume DECIMAL(28,6) NULL,InvoiceValue DECIMAL(28,6) NULL,FOREIGN KEY(ShipmentId) REFERENCES imp.Shipment(ShipmentId),FOREIGN KEY(ItemId) REFERENCES inv.Item(ItemId),FOREIGN KEY(POLineId) REFERENCES ap.PurchaseOrderLine(POLineId),CHECK(Quantity>0));
CREATE TABLE imp.CustomsDeclaration(CustomsDeclarationId BIGINT IDENTITY PRIMARY KEY,ImportCaseId BIGINT NOT NULL,ShipmentId BIGINT NULL,DeclarationNumber VARCHAR(100) NOT NULL,DeclarationDate DATE NULL,CustomsValue DECIMAL(28,6) NULL,CurrencyCode CHAR(3) NULL,FOREIGN KEY(ImportCaseId) REFERENCES imp.ImportCase(ImportCaseId),FOREIGN KEY(ShipmentId) REFERENCES imp.Shipment(ShipmentId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),UNIQUE(DeclarationNumber));
CREATE TABLE imp.ImportCost(ImportCostId BIGINT IDENTITY PRIMARY KEY,ImportCaseId BIGINT NOT NULL,ShipmentId BIGINT NULL,CostType VARCHAR(30) NOT NULL,CurrencyCode CHAR(3) NOT NULL,OriginalAmount DECIMAL(28,6) NOT NULL,ExchangeRate DECIMAL(28,12) NOT NULL DEFAULT(1),BaseAmount AS (OriginalAmount*ExchangeRate) PERSISTED,Reference VARCHAR(100) NULL,FOREIGN KEY(ImportCaseId) REFERENCES imp.ImportCase(ImportCaseId),FOREIGN KEY(ShipmentId) REFERENCES imp.Shipment(ShipmentId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),CHECK(CostType IN('FREIGHT','INSURANCE','CUSTOMS','DUTY','CLEARANCE','HANDLING','OTHER')),CHECK(OriginalAmount>=0 AND ExchangeRate>0));
CREATE TABLE imp.GoodsInTransit(GITId BIGINT IDENTITY PRIMARY KEY,ImportCaseId BIGINT NOT NULL,ShipmentItemId BIGINT NOT NULL,AsOfDate DATE NOT NULL,Quantity DECIMAL(28,6) NOT NULL,ValueAmount DECIMAL(28,6) NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('IN_TRANSIT'),FOREIGN KEY(ImportCaseId) REFERENCES imp.ImportCase(ImportCaseId),FOREIGN KEY(ShipmentItemId) REFERENCES imp.ShipmentItem(ShipmentItemId),CHECK(Quantity>=0 AND ValueAmount>=0));
CREATE TABLE imp.LandedCostBatch(LandedCostBatchId BIGINT IDENTITY PRIMARY KEY,ImportCaseId BIGINT NOT NULL,BatchNumber VARCHAR(50) NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('DRAFT'),AllocationDate DATE NULL,CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),FOREIGN KEY(ImportCaseId) REFERENCES imp.ImportCase(ImportCaseId),UNIQUE(ImportCaseId,BatchNumber));
CREATE TABLE imp.LandedCostPool(LandedCostPoolId BIGINT IDENTITY PRIMARY KEY,LandedCostBatchId BIGINT NOT NULL,ImportCostId BIGINT NULL,CostType VARCHAR(30) NOT NULL,CurrencyCode CHAR(3) NOT NULL,OriginalAmount DECIMAL(28,6) NOT NULL,ExchangeRate DECIMAL(28,12) NOT NULL DEFAULT(1),BaseAmount DECIMAL(28,6) NOT NULL,AllocationMethod VARCHAR(20) NOT NULL,FOREIGN KEY(LandedCostBatchId) REFERENCES imp.LandedCostBatch(LandedCostBatchId),FOREIGN KEY(ImportCostId) REFERENCES imp.ImportCost(ImportCostId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),CHECK(AllocationMethod IN('QUANTITY','VALUE','WEIGHT','VOLUME','MANUAL')),CHECK(OriginalAmount>=0 AND ExchangeRate>0 AND BaseAmount>=0));
CREATE TABLE imp.LandedCostAllocation(LandedCostAllocationId BIGINT IDENTITY PRIMARY KEY,LandedCostPoolId BIGINT NOT NULL,ShipmentItemId BIGINT NOT NULL,ItemId BIGINT NOT NULL,AllocationBasis DECIMAL(28,6) NULL,BasisValue DECIMAL(28,6) NULL,AllocationPercentage DECIMAL(19,10) NULL,AllocatedAmount DECIMAL(28,6) NOT NULL,FOREIGN KEY(LandedCostPoolId) REFERENCES imp.LandedCostPool(LandedCostPoolId),FOREIGN KEY(ShipmentItemId) REFERENCES imp.ShipmentItem(ShipmentItemId),FOREIGN KEY(ItemId) REFERENCES inv.Item(ItemId),CHECK(AllocatedAmount>=0),CHECK(AllocationPercentage IS NULL OR (AllocationPercentage>=0 AND AllocationPercentage<=100)));

CREATE TABLE trs.Bank(BankId BIGINT IDENTITY PRIMARY KEY,BankCode VARCHAR(30) NOT NULL UNIQUE,BankName NVARCHAR(200) NOT NULL);
CREATE TABLE trs.BankAccount(BankAccountId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,BankId BIGINT NOT NULL,AccountNumberMasked VARCHAR(100) NOT NULL,CurrencyCode CHAR(3) NOT NULL,IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(BankId) REFERENCES trs.Bank(BankId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode));
CREATE TABLE trs.BankStatement(BankStatementId BIGINT IDENTITY PRIMARY KEY,BankAccountId BIGINT NOT NULL,StatementDate DATE NOT NULL,OpeningBalance DECIMAL(28,6) NOT NULL,ClosingBalance DECIMAL(28,6) NOT NULL,FOREIGN KEY(BankAccountId) REFERENCES trs.BankAccount(BankAccountId),UNIQUE(BankAccountId,StatementDate));
CREATE TABLE trs.BankStatementLine(BankStatementLineId BIGINT IDENTITY PRIMARY KEY,BankStatementId BIGINT NOT NULL,LineNo INT NOT NULL,ValueDate DATE NOT NULL,Reference VARCHAR(150) NULL,Description NVARCHAR(500),DebitAmount DECIMAL(28,6) NOT NULL DEFAULT(0),CreditAmount DECIMAL(28,6) NOT NULL DEFAULT(0),FOREIGN KEY(BankStatementId) REFERENCES trs.BankStatement(BankStatementId),CHECK((DebitAmount>0 AND CreditAmount=0) OR (CreditAmount>0 AND DebitAmount=0)),UNIQUE(BankStatementId,LineNo));
CREATE TABLE trs.PaymentProposal(PaymentProposalId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,CompanyId BIGINT NOT NULL,VendorId BIGINT NOT NULL,ProposalDate DATE NOT NULL,CurrencyCode CHAR(3) NOT NULL,Amount DECIMAL(28,6) NOT NULL,Status VARCHAR(25) NOT NULL DEFAULT('PROPOSED'),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(VendorId) REFERENCES ap.Vendor(VendorId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),CHECK(Amount>0));
CREATE TABLE trs.Payment(PaymentId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,PaymentProposalId BIGINT NULL,BankAccountId BIGINT NOT NULL,PaymentDate DATE NOT NULL,CurrencyCode CHAR(3) NOT NULL,Amount DECIMAL(28,6) NOT NULL,PaymentReference VARCHAR(100) NULL,Status VARCHAR(25) NOT NULL DEFAULT('PENDING'),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(PaymentProposalId) REFERENCES trs.PaymentProposal(PaymentProposalId),FOREIGN KEY(BankAccountId) REFERENCES trs.BankAccount(BankAccountId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),CHECK(Amount>0));
CREATE TABLE trs.PaymentAllocation(PaymentAllocationId BIGINT IDENTITY PRIMARY KEY,PaymentId BIGINT NOT NULL,InvoiceId BIGINT NOT NULL,AllocatedAmount DECIMAL(28,6) NOT NULL,FOREIGN KEY(PaymentId) REFERENCES trs.Payment(PaymentId),FOREIGN KEY(InvoiceId) REFERENCES ap.SupplierInvoice(InvoiceId),CHECK(AllocatedAmount>0),UNIQUE(PaymentId,InvoiceId));
CREATE TABLE trs.BankReconciliation(BankReconciliationId BIGINT IDENTITY PRIMARY KEY,BankAccountId BIGINT NOT NULL,ReconciliationDate DATE NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('OPEN'),StartedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CompletedAt DATETIME2(3) NULL,FOREIGN KEY(BankAccountId) REFERENCES trs.BankAccount(BankAccountId),UNIQUE(BankAccountId,ReconciliationDate));
CREATE TABLE trs.ReconciliationLine(ReconciliationLineId BIGINT IDENTITY PRIMARY KEY,BankReconciliationId BIGINT NOT NULL,BankStatementLineId BIGINT NOT NULL,JournalLineId BIGINT NULL,PaymentId BIGINT NULL,MatchStatus VARCHAR(20) NOT NULL,VarianceAmount DECIMAL(28,6) NOT NULL DEFAULT(0),FOREIGN KEY(BankReconciliationId) REFERENCES trs.BankReconciliation(BankReconciliationId),FOREIGN KEY(BankStatementLineId) REFERENCES trs.BankStatementLine(BankStatementLineId),FOREIGN KEY(JournalLineId) REFERENCES acc.JournalLine(JournalLineId),FOREIGN KEY(PaymentId) REFERENCES trs.Payment(PaymentId));
CREATE TABLE trs.CashPosition(CashPositionId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,PositionDate DATE NOT NULL,CurrencyCode CHAR(3) NOT NULL,AvailableCash DECIMAL(28,6) NOT NULL,RestrictedCash DECIMAL(28,6) NOT NULL DEFAULT(0),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),UNIQUE(CompanyId,PositionDate,CurrencyCode));
CREATE TABLE trs.CashForecast(CashForecastId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,ForecastDate DATE NOT NULL,CurrencyCode CHAR(3) NOT NULL,ExpectedInflows DECIMAL(28,6) NOT NULL DEFAULT(0),ExpectedOutflows DECIMAL(28,6) NOT NULL DEFAULT(0),Scenario VARCHAR(30) NOT NULL DEFAULT('BASE'),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode));
CREATE TABLE trs.FXExposure(FXExposureId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,AsOfDate DATE NOT NULL,CurrencyCode CHAR(3) NOT NULL,AssetExposure DECIMAL(28,6) NOT NULL DEFAULT(0),LiabilityExposure DECIMAL(28,6) NOT NULL DEFAULT(0),NetExposure AS (AssetExposure-LiabilityExposure) PERSISTED,FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode));

CREATE TABLE tax.TaxType(TaxTypeId BIGINT IDENTITY PRIMARY KEY,TaxTypeCode VARCHAR(30) NOT NULL UNIQUE,TaxTypeName NVARCHAR(150) NOT NULL);
CREATE TABLE tax.TaxCode(TaxCodeId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,TaxTypeId BIGINT NOT NULL,TaxCode VARCHAR(30) NOT NULL,Description NVARCHAR(250),IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(TaxTypeId) REFERENCES tax.TaxType(TaxTypeId),UNIQUE(CompanyId,TaxCode));
CREATE TABLE tax.TaxRate(TaxRateId BIGINT IDENTITY PRIMARY KEY,TaxCodeId BIGINT NOT NULL,ValidFrom DATE NOT NULL,ValidTo DATE NULL,Rate DECIMAL(12,8) NOT NULL,FOREIGN KEY(TaxCodeId) REFERENCES tax.TaxCode(TaxCodeId),CHECK(Rate>=0));
CREATE TABLE tax.TaxTransaction(TaxTransactionId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,CompanyId BIGINT NOT NULL,TaxCodeId BIGINT NOT NULL,TaxDate DATE NOT NULL,TaxableBase DECIMAL(28,6) NOT NULL,TaxAmount DECIMAL(28,6) NOT NULL,SourceModule VARCHAR(30) NOT NULL,SourceEntityId BIGINT NULL,FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(TaxCodeId) REFERENCES tax.TaxCode(TaxCodeId));
CREATE TABLE tax.TaxPeriod(TaxPeriodId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,TaxTypeId BIGINT NOT NULL,PeriodStart DATE NOT NULL,PeriodEnd DATE NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('OPEN'),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(TaxTypeId) REFERENCES tax.TaxType(TaxTypeId),CHECK(PeriodStart<=PeriodEnd));
CREATE TABLE tax.TaxReturn(TaxReturnId BIGINT IDENTITY PRIMARY KEY,TaxPeriodId BIGINT NOT NULL,ReturnReference VARCHAR(100) NULL,PreparedAmount DECIMAL(28,6) NULL,FiledAmount DECIMAL(28,6) NULL,Status VARCHAR(20) NOT NULL DEFAULT('DRAFT'),PreparedBy BIGINT NULL,ApprovedBy BIGINT NULL,FiledAt DATETIME2(3) NULL,FOREIGN KEY(TaxPeriodId) REFERENCES tax.TaxPeriod(TaxPeriodId),FOREIGN KEY(PreparedBy) REFERENCES core.AppUser(UserId),FOREIGN KEY(ApprovedBy) REFERENCES core.AppUser(UserId));
CREATE TABLE tax.TaxReturnLine(TaxReturnLineId BIGINT IDENTITY PRIMARY KEY,TaxReturnId BIGINT NOT NULL,LineCode VARCHAR(50) NOT NULL,Description NVARCHAR(250),TaxableBase DECIMAL(28,6) NULL,TaxAmount DECIMAL(28,6) NULL,FOREIGN KEY(TaxReturnId) REFERENCES tax.TaxReturn(TaxReturnId),UNIQUE(TaxReturnId,LineCode));
CREATE TABLE tax.TaxReconciliation(TaxReconciliationId BIGINT IDENTITY PRIMARY KEY,TaxPeriodId BIGINT NOT NULL,GLAmount DECIMAL(28,6) NOT NULL,ReturnAmount DECIMAL(28,6) NOT NULL,Difference AS (GLAmount-ReturnAmount) PERSISTED,Status VARCHAR(20) NOT NULL DEFAULT('OPEN'),FOREIGN KEY(TaxPeriodId) REFERENCES tax.TaxPeriod(TaxPeriodId));

CREATE TABLE pay.PayrollRun(PayrollRunId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,PeriodStart DATE NOT NULL,PeriodEnd DATE NOT NULL,RunNumber VARCHAR(50) NOT NULL,Status VARCHAR(25) NOT NULL DEFAULT('DRAFT'),GrossPay DECIMAL(28,6) NULL,Deductions DECIMAL(28,6) NULL,NetPay DECIMAL(28,6) NULL,FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),UNIQUE(CompanyId,RunNumber));
CREATE TABLE pay.PayrollAccounting(PayrollAccountingId BIGINT IDENTITY PRIMARY KEY,PayrollRunId BIGINT NOT NULL,JournalId BIGINT NULL,Status VARCHAR(20) NOT NULL DEFAULT('UNPOSTED'),FOREIGN KEY(PayrollRunId) REFERENCES pay.PayrollRun(PayrollRunId),FOREIGN KEY(JournalId) REFERENCES acc.JournalHeader(JournalId));

CREATE TABLE fpna.Budget(BudgetId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,BudgetCode VARCHAR(50) NOT NULL,FiscalYearId BIGINT NOT NULL,Scenario VARCHAR(30) NOT NULL DEFAULT('BASE'),Status VARCHAR(20) NOT NULL DEFAULT('DRAFT'),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(FiscalYearId) REFERENCES core.FiscalYear(FiscalYearId),UNIQUE(CompanyId,BudgetCode));
CREATE TABLE fpna.BudgetLine(BudgetLineId BIGINT IDENTITY PRIMARY KEY,BudgetId BIGINT NOT NULL,FiscalPeriodId BIGINT NOT NULL,AccountId BIGINT NOT NULL,CostCenterId BIGINT NULL,Amount DECIMAL(28,6) NOT NULL,FOREIGN KEY(BudgetId) REFERENCES fpna.Budget(BudgetId),FOREIGN KEY(FiscalPeriodId) REFERENCES core.FiscalPeriod(FiscalPeriodId),FOREIGN KEY(AccountId) REFERENCES acc.Account(AccountId),FOREIGN KEY(CostCenterId) REFERENCES core.CostCenter(CostCenterId));
CREATE TABLE fpna.Forecast(ForecastId BIGINT IDENTITY PRIMARY KEY,CompanyId BIGINT NOT NULL,ForecastCode VARCHAR(50) NOT NULL,AsOfDate DATE NOT NULL,Scenario VARCHAR(30) NOT NULL DEFAULT('BASE'),Status VARCHAR(20) NOT NULL DEFAULT('DRAFT'),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),UNIQUE(CompanyId,ForecastCode));
CREATE TABLE fpna.ForecastLine(ForecastLineId BIGINT IDENTITY PRIMARY KEY,ForecastId BIGINT NOT NULL,FiscalPeriodId BIGINT NOT NULL,AccountId BIGINT NOT NULL,CostCenterId BIGINT NULL,Amount DECIMAL(28,6) NOT NULL,FOREIGN KEY(ForecastId) REFERENCES fpna.Forecast(ForecastId),FOREIGN KEY(FiscalPeriodId) REFERENCES core.FiscalPeriod(FiscalPeriodId),FOREIGN KEY(AccountId) REFERENCES acc.Account(AccountId),FOREIGN KEY(CostCenterId) REFERENCES core.CostCenter(CostCenterId));

CREATE TABLE ctrl.ControlDefinition(ControlDefinitionId BIGINT IDENTITY PRIMARY KEY,ControlCode VARCHAR(50) NOT NULL UNIQUE,ControlName NVARCHAR(200) NOT NULL,Domain VARCHAR(30) NOT NULL,SeverityDefault VARCHAR(10) NOT NULL,IsActive BIT NOT NULL DEFAULT(1));
CREATE TABLE ctrl.ControlRule(ControlRuleId BIGINT IDENTITY PRIMARY KEY,ControlDefinitionId BIGINT NOT NULL,RuleVersion INT NOT NULL,RuleExpression NVARCHAR(MAX) NULL,EffectiveFrom DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),EffectiveTo DATETIME2(3) NULL,FOREIGN KEY(ControlDefinitionId) REFERENCES ctrl.ControlDefinition(ControlDefinitionId),UNIQUE(ControlDefinitionId,RuleVersion));
CREATE TABLE ctrl.ControlExecution(ControlExecutionId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,ControlRuleId BIGINT NOT NULL,ExecutedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Result VARCHAR(10) NOT NULL,ResultDetail NVARCHAR(2000) NULL,FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(ControlRuleId) REFERENCES ctrl.ControlRule(ControlRuleId),CHECK(Result IN('PASS','WARNING','FAIL','BLOCK')));
CREATE TABLE ctrl.Exception(ExceptionId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NULL,ControlExecutionId BIGINT NULL,ExceptionCode VARCHAR(50) NOT NULL,Severity VARCHAR(10) NOT NULL,Reason NVARCHAR(1000) NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('OPEN'),AssignedRoleId BIGINT NULL,CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),ResolvedAt DATETIME2(3) NULL,FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(ControlExecutionId) REFERENCES ctrl.ControlExecution(ControlExecutionId),FOREIGN KEY(AssignedRoleId) REFERENCES core.AppRole(RoleId),CHECK(Severity IN('E0','E1','E2','E3','E4')));
CREATE TABLE ctrl.ExceptionEvidence(ExceptionEvidenceId BIGINT IDENTITY PRIMARY KEY,ExceptionId BIGINT NOT NULL,EvidenceType VARCHAR(40) NOT NULL,EvidenceReference VARCHAR(500) NOT NULL,FOREIGN KEY(ExceptionId) REFERENCES ctrl.Exception(ExceptionId));
CREATE TABLE ctrl.ExceptionResolution(ExceptionResolutionId BIGINT IDENTITY PRIMARY KEY,ExceptionId BIGINT NOT NULL,ResolvedBy BIGINT NOT NULL,ResolutionCode VARCHAR(30) NOT NULL,ResolutionNote NVARCHAR(2000) NULL,ResolvedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),FOREIGN KEY(ExceptionId) REFERENCES ctrl.Exception(ExceptionId),FOREIGN KEY(ResolvedBy) REFERENCES core.AppUser(UserId));
CREATE TABLE ctrl.ApprovalPolicy(ApprovalPolicyId BIGINT IDENTITY PRIMARY KEY,PolicyCode VARCHAR(50) NOT NULL UNIQUE,CompanyId BIGINT NULL,TransactionType VARCHAR(40) NOT NULL,IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId));
CREATE TABLE ctrl.ApprovalRule(ApprovalRuleId BIGINT IDENTITY PRIMARY KEY,ApprovalPolicyId BIGINT NOT NULL,RuleOrder INT NOT NULL,AmountFrom DECIMAL(28,6) NULL,AmountTo DECIMAL(28,6) NULL,CurrencyCode CHAR(3) NULL,RiskLevel VARCHAR(20) NULL,ExceptionLevel VARCHAR(10) NULL,RequiredRoleId BIGINT NOT NULL,FOREIGN KEY(ApprovalPolicyId) REFERENCES ctrl.ApprovalPolicy(ApprovalPolicyId),FOREIGN KEY(CurrencyCode) REFERENCES core.Currency(CurrencyCode),FOREIGN KEY(RequiredRoleId) REFERENCES core.AppRole(RoleId),UNIQUE(ApprovalPolicyId,RuleOrder));
CREATE TABLE ctrl.ApprovalInstance(ApprovalInstanceId BIGINT IDENTITY PRIMARY KEY,TransactionId BIGINT NOT NULL,ApprovalPolicyId BIGINT NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('PENDING'),CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CompletedAt DATETIME2(3) NULL,FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(ApprovalPolicyId) REFERENCES ctrl.ApprovalPolicy(ApprovalPolicyId));
CREATE TABLE ctrl.ApprovalStep(ApprovalStepId BIGINT IDENTITY PRIMARY KEY,ApprovalInstanceId BIGINT NOT NULL,StepNo INT NOT NULL,RequiredRoleId BIGINT NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('PENDING'),FOREIGN KEY(ApprovalInstanceId) REFERENCES ctrl.ApprovalInstance(ApprovalInstanceId),FOREIGN KEY(RequiredRoleId) REFERENCES core.AppRole(RoleId),UNIQUE(ApprovalInstanceId,StepNo));
CREATE TABLE ctrl.ApprovalDecision(ApprovalDecisionId BIGINT IDENTITY PRIMARY KEY,ApprovalStepId BIGINT NOT NULL,UserId BIGINT NOT NULL,Decision VARCHAR(20) NOT NULL,DecisionAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Comment NVARCHAR(1000) NULL,FOREIGN KEY(ApprovalStepId) REFERENCES ctrl.ApprovalStep(ApprovalStepId),FOREIGN KEY(UserId) REFERENCES core.AppUser(UserId),CHECK(Decision IN('APPROVE','REJECT','RETURN','ESCALATE')));

CREATE TABLE ai.Agent(AgentId BIGINT IDENTITY PRIMARY KEY,AgentCode VARCHAR(30) NOT NULL UNIQUE,AgentName NVARCHAR(200) NOT NULL,Domain VARCHAR(30) NOT NULL,Version VARCHAR(20) NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('ACTIVE'),RiskLevel VARCHAR(20) NOT NULL DEFAULT('MEDIUM'),Description NVARCHAR(1000));
CREATE TABLE ai.AgentCapability(AgentCapabilityId BIGINT IDENTITY PRIMARY KEY,AgentId BIGINT NOT NULL,CapabilityCode VARCHAR(50) NOT NULL,CapabilityName NVARCHAR(200) NOT NULL,FOREIGN KEY(AgentId) REFERENCES ai.Agent(AgentId),UNIQUE(AgentId,CapabilityCode));
CREATE TABLE ai.AgentPermission(AgentPermissionId BIGINT IDENTITY PRIMARY KEY,AgentId BIGINT NOT NULL,ResourceCode VARCHAR(100) NOT NULL,PermissionLevel VARCHAR(20) NOT NULL,IsAllowed BIT NOT NULL DEFAULT(1),FOREIGN KEY(AgentId) REFERENCES ai.Agent(AgentId),CHECK(PermissionLevel IN('READ','ANALYZE','RECOMMEND','PREPARE','EXECUTE_CONTROLLED')));
CREATE TABLE ai.AgentTool(AgentToolId BIGINT IDENTITY PRIMARY KEY,AgentId BIGINT NOT NULL,ToolCode VARCHAR(100) NOT NULL,ToolName NVARCHAR(200) NOT NULL,IsEnabled BIT NOT NULL DEFAULT(1),FOREIGN KEY(AgentId) REFERENCES ai.Agent(AgentId),UNIQUE(AgentId,ToolCode));
CREATE TABLE ai.OrchestrationRun(OrchestrationRunId BIGINT IDENTITY PRIMARY KEY,RequestId VARCHAR(100) NOT NULL,TransactionId BIGINT NULL,StartedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CompletedAt DATETIME2(3) NULL,Status VARCHAR(20) NOT NULL DEFAULT('RUNNING'),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),UNIQUE(RequestId));
CREATE TABLE ai.AgentRun(AgentRunId BIGINT IDENTITY PRIMARY KEY,AgentId BIGINT NOT NULL,TransactionId BIGINT NULL,OrchestrationRunId BIGINT NULL,StartedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CompletedAt DATETIME2(3) NULL,InputSchemaVersion VARCHAR(20) NULL,OutputSchemaVersion VARCHAR(20) NULL,RunStatus VARCHAR(20) NOT NULL DEFAULT('RUNNING'),Confidence DECIMAL(9,6) NULL,ModelReference VARCHAR(200) NULL,PromptVersion VARCHAR(50) NULL,RequiresHumanReview BIT NOT NULL DEFAULT(0),ExceptionCount INT NOT NULL DEFAULT(0),FOREIGN KEY(AgentId) REFERENCES ai.Agent(AgentId),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(OrchestrationRunId) REFERENCES ai.OrchestrationRun(OrchestrationRunId),CHECK(Confidence IS NULL OR (Confidence>=0 AND Confidence<=1)),CHECK(ExceptionCount>=0));
CREATE TABLE ai.AgentInput(AgentInputId BIGINT IDENTITY PRIMARY KEY,AgentRunId BIGINT NOT NULL,Payload JSON NOT NULL,CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),FOREIGN KEY(AgentRunId) REFERENCES ai.AgentRun(AgentRunId));
CREATE TABLE ai.AgentOutput(AgentOutputId BIGINT IDENTITY PRIMARY KEY,AgentRunId BIGINT NOT NULL,Payload JSON NOT NULL,CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),FOREIGN KEY(AgentRunId) REFERENCES ai.AgentRun(AgentRunId));
CREATE TABLE ai.AgentDecision(AgentDecisionId BIGINT IDENTITY PRIMARY KEY,AgentRunId BIGINT NOT NULL,DecisionCode VARCHAR(50) NOT NULL,Recommendation NVARCHAR(2000) NULL,StructuredResult JSON NULL,CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),FOREIGN KEY(AgentRunId) REFERENCES ai.AgentRun(AgentRunId));
CREATE TABLE ai.AgentEvidence(AgentEvidenceId BIGINT IDENTITY PRIMARY KEY,AgentRunId BIGINT NOT NULL,EvidenceType VARCHAR(40) NOT NULL,EvidenceReference VARCHAR(500) NOT NULL,HashValue VARCHAR(128) NULL,FOREIGN KEY(AgentRunId) REFERENCES ai.AgentRun(AgentRunId));
CREATE TABLE ai.OrchestrationStep(OrchestrationStepId BIGINT IDENTITY PRIMARY KEY,OrchestrationRunId BIGINT NOT NULL,StepNo INT NOT NULL,AgentId BIGINT NULL,ActionCode VARCHAR(50) NOT NULL,Status VARCHAR(20) NOT NULL,StartedAt DATETIME2(3) NULL,CompletedAt DATETIME2(3) NULL,FOREIGN KEY(OrchestrationRunId) REFERENCES ai.OrchestrationRun(OrchestrationRunId),FOREIGN KEY(AgentId) REFERENCES ai.Agent(AgentId),UNIQUE(OrchestrationRunId,StepNo));

CREATE TABLE integration.ExternalSystem(ExternalSystemId BIGINT IDENTITY PRIMARY KEY,SystemCode VARCHAR(50) NOT NULL UNIQUE,SystemName NVARCHAR(200) NOT NULL,IsActive BIT NOT NULL DEFAULT(1));
CREATE TABLE integration.EntityMapping(EntityMappingId BIGINT IDENTITY PRIMARY KEY,ExternalSystemId BIGINT NOT NULL,EntityType VARCHAR(50) NOT NULL,InternalId BIGINT NOT NULL,ExternalId VARCHAR(200) NOT NULL,FOREIGN KEY(ExternalSystemId) REFERENCES integration.ExternalSystem(ExternalSystemId),UNIQUE(ExternalSystemId,EntityType,ExternalId));
CREATE TABLE integration.InboundMessage(InboundMessageId BIGINT IDENTITY PRIMARY KEY,ExternalSystemId BIGINT NOT NULL,MessageType VARCHAR(50) NOT NULL,ExternalMessageId VARCHAR(200) NULL,Payload JSON NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('RECEIVED'),ReceivedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),FOREIGN KEY(ExternalSystemId) REFERENCES integration.ExternalSystem(ExternalSystemId));
CREATE TABLE integration.OutboundMessage(OutboundMessageId BIGINT IDENTITY PRIMARY KEY,ExternalSystemId BIGINT NOT NULL,MessageType VARCHAR(50) NOT NULL,Payload JSON NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('PENDING'),CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),SentAt DATETIME2(3) NULL,FOREIGN KEY(ExternalSystemId) REFERENCES integration.ExternalSystem(ExternalSystemId));
CREATE TABLE integration.SyncJob(SyncJobId BIGINT IDENTITY PRIMARY KEY,ExternalSystemId BIGINT NOT NULL,JobCode VARCHAR(50) NOT NULL,EntityType VARCHAR(50) NOT NULL,Direction VARCHAR(10) NOT NULL,IsActive BIT NOT NULL DEFAULT(1),FOREIGN KEY(ExternalSystemId) REFERENCES integration.ExternalSystem(ExternalSystemId),CHECK(Direction IN('INBOUND','OUTBOUND','BOTH')),UNIQUE(ExternalSystemId,JobCode));
CREATE TABLE integration.SyncLog(SyncLogId BIGINT IDENTITY PRIMARY KEY,SyncJobId BIGINT NOT NULL,StartedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CompletedAt DATETIME2(3) NULL,Status VARCHAR(20) NOT NULL,RowsProcessed INT NOT NULL DEFAULT(0),ErrorMessage NVARCHAR(2000) NULL,FOREIGN KEY(SyncJobId) REFERENCES integration.SyncJob(SyncJobId));
CREATE TABLE integration.ErrorQueue(ErrorQueueId BIGINT IDENTITY PRIMARY KEY,ExternalSystemId BIGINT NULL,EntityType VARCHAR(50) NULL,ReferenceId VARCHAR(200) NULL,ErrorCode VARCHAR(50) NULL,ErrorMessage NVARCHAR(2000) NOT NULL,Status VARCHAR(20) NOT NULL DEFAULT('OPEN'),CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),FOREIGN KEY(ExternalSystemId) REFERENCES integration.ExternalSystem(ExternalSystemId));

/* Append-only audit event. Keep audit as facts/events; corrections are new events, not updates. */
CREATE TABLE audit.Event(
 AuditEventId BIGINT IDENTITY PRIMARY KEY,
 TransactionId BIGINT NULL,
 CorrelationId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
 EventType VARCHAR(50) NOT NULL,
 EntityType VARCHAR(50) NOT NULL,
 EntityId BIGINT NULL,
 ActorType VARCHAR(20) NOT NULL,
 ActorId VARCHAR(100) NULL,
 AgentRunId BIGINT NULL,
 Action VARCHAR(100) NOT NULL,
 OldValue JSON NULL,
 NewValue JSON NULL,
 EventAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),
 SourceSystem VARCHAR(50) NULL,
 FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),
 FOREIGN KEY(AgentRunId) REFERENCES ai.AgentRun(AgentRunId)
) WITH (LEDGER = ON, APPEND_ONLY = ON);

/* High-value indexes */
CREATE INDEX IX_BusinessTransaction_CompanyTypeStatus ON core.BusinessTransaction(CompanyId,TransactionType,Status);
CREATE INDEX IX_JournalHeader_PostingDateStatus ON acc.JournalHeader(CompanyId,PostingDate,Status);
CREATE INDEX IX_JournalLine_Account ON acc.JournalLine(AccountId,JournalId);
CREATE INDEX IX_APInvoice_VendorDue ON ap.SupplierInvoice(CompanyId,VendorId,DueDate,ApprovalStatus);
CREATE INDEX IX_ARInvoice_CustomerDue ON ar.SalesInvoice(CompanyId,CustomerId,DueDate,Status);
CREATE INDEX IX_InventoryTxn_ItemDate ON inv.InventoryTransaction(CompanyId,ItemId,TransactionDate);
CREATE INDEX IX_ImportCost_CaseType ON imp.ImportCost(ImportCaseId,CostType);
CREATE INDEX IX_BankStmtLine_Statement ON trs.BankStatementLine(BankStatementId,ValueDate);
CREATE INDEX IX_ControlExecution_Txn ON ctrl.ControlExecution(TransactionId,ExecutedAt);
CREATE INDEX IX_Exception_Open ON ctrl.Exception(Status,Severity,CreatedAt) INCLUDE(TransactionId,AssignedRoleId);
CREATE INDEX IX_AgentRun_Txn ON ai.AgentRun(TransactionId,StartedAt);
CREATE INDEX IX_Audit_Transaction ON audit.Event(TransactionId,EventAt);
GO

/* Operational views */
CREATE VIEW acc.vwTrialBalance AS
SELECT h.CompanyId,l.AccountId,a.AccountCode,a.AccountNameAr,
       SUM(l.Debit) AS DebitTotal,SUM(l.Credit) AS CreditTotal,SUM(l.Debit-l.Credit) AS Balance
FROM acc.JournalHeader h JOIN acc.JournalLine l ON l.JournalId=h.JournalId
JOIN acc.Account a ON a.AccountId=l.AccountId
WHERE h.Status='POSTED'
GROUP BY h.CompanyId,l.AccountId,a.AccountCode,a.AccountNameAr;
GO
CREATE VIEW ap.vwOpenPayables AS
SELECT i.CompanyId,i.InvoiceId,i.VendorId,v.VendorCode,v.VendorName,i.InvoiceNumber,i.InvoiceDate,i.DueDate,i.CurrencyCode,i.NetAmount,i.ApprovalStatus,i.PostingStatus
FROM ap.SupplierInvoice i JOIN ap.Vendor v ON v.VendorId=i.VendorId
WHERE i.PostingStatus<>'REVERSED';
GO
CREATE VIEW ar.vwOpenReceivables AS
SELECT i.CompanyId,i.SalesInvoiceId,i.CustomerId,c.CustomerCode,c.CustomerName,i.InvoiceNumber,i.InvoiceDate,i.DueDate,i.CurrencyCode,i.NetAmount,i.Status
FROM ar.SalesInvoice i JOIN ar.Customer c ON c.CustomerId=i.CustomerId
WHERE i.Status='OPEN';
GO

/* Controlled posting gate: deterministic validation + transaction. */
CREATE OR ALTER PROCEDURE acc.usp_PostJournal @JournalId BIGINT, @ApproverUserId BIGINT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRAN;
 IF NOT EXISTS(SELECT 1 FROM acc.JournalHeader WITH(UPDLOCK,HOLDLOCK) WHERE JournalId=@JournalId AND Status='APPROVED')
   THROW 51001,'Journal must exist and be APPROVED before posting.',1;
 IF EXISTS(SELECT 1 FROM acc.JournalHeader h JOIN core.FiscalYear fy ON fy.CompanyId=h.CompanyId JOIN core.FiscalPeriod fp ON fp.FiscalYearId=fy.FiscalYearId AND h.PostingDate BETWEEN fp.StartDate AND fp.EndDate WHERE h.JournalId=@JournalId AND fp.Status='CLOSED')
   THROW 51002,'Posting period is closed.',1;
 IF ABS((SELECT COALESCE(SUM(Debit-Credit),0) FROM acc.JournalLine WHERE JournalId=@JournalId)) > 0.000001
   THROW 51003,'Journal is not balanced.',1;
 IF (SELECT COUNT(*) FROM acc.JournalLine WHERE JournalId=@JournalId)<2
   THROW 51004,'Journal requires at least two lines.',1;
 UPDATE acc.JournalHeader SET Status='POSTED',ApprovedBy=COALESCE(ApprovedBy,@ApproverUserId),PostedAt=SYSUTCDATETIME() WHERE JournalId=@JournalId;
 COMMIT;
END;
GO

/* Landed-cost reconciliation gate. */
CREATE OR ALTER PROCEDURE imp.usp_CloseLandedCostBatch @LandedCostBatchId BIGINT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRAN;
 IF EXISTS(
   SELECT 1 FROM imp.LandedCostPool p
   OUTER APPLY(SELECT SUM(a.AllocatedAmount) Allocated FROM imp.LandedCostAllocation a WHERE a.LandedCostPoolId=p.LandedCostPoolId) x
   WHERE p.LandedCostBatchId=@LandedCostBatchId AND ABS(p.BaseAmount-COALESCE(x.Allocated,0))>0.000001)
   THROW 51010,'Landed cost pool is not fully reconciled to allocations.',1;
 UPDATE imp.LandedCostBatch SET Status='CLOSED',AllocationDate=COALESCE(AllocationDate,CAST(SYSUTCDATETIME() AS DATE)) WHERE LandedCostBatchId=@LandedCostBatchId;
 COMMIT;
END;
GO
